import{parseAgentEvent}from'./event.js';
import{DEFAULT_LIMITS,createAgentState,reduce}from'./reduce.js';
export function createAgentStore(options={}){
const limits=Object.freeze({...DEFAULT_LIMITS,...options.limits});
for(const key of['maxActivity','maxTextChars','maxEntities']){
if(!Number.isSafeInteger(limits[key])||limits[key]<1)
throw new RangeError(key);
}
let state=options.initial??createAgentState();
let dropped=0;
const listeners=new Set();
const notify=()=>{
for(const listener of[...listeners]){
try{
listener();
}
catch(error){
console.error(error);
}
}
};
return{
getSnapshot:()=>state,
subscribe(listener){
listeners.add(listener);
return()=>listeners.delete(listener);
},
apply(input){
const events=[];
for(const raw of input){
const event=parseAgentEvent(raw);
if(event)
events.push(event);
else
dropped+=1;
}
events.sort((a,b)=>a.seq-b.seq);
const before=state;
let changed=0;
for(const event of events){
const next=reduce(state,event,limits);
if(next!==state)
changed+=1;
state=next;
}
if(state!==before)
notify();
return changed;
},
reset(next=createAgentState()){
if(next===state)
return;
state=next;
notify();
},
get dropped(){
return dropped;
},
};
}
